import click
from click.testing import CliRunner
r = CliRunner()

@click.command()
@click.option("--foo", is_flag=True, required=True)
def cli(foo):
    click.echo(foo)

res = r.invoke(cli, [])
print("required flag missing:", repr(res.output), res.exit_code)
res = r.invoke(cli, ["--foo"])
print("required flag given:", repr(res.output), res.exit_code)

@click.command()
@click.option("--flag", is_flag=True, multiple=True)
def cli2(flag):
    click.echo(repr(flag))
print("multi flag:", repr(r.invoke(cli2, []).output), repr(r.invoke(cli2, ["--flag"]).output))

# argument decorator cls preservation
class CustomArgument(click.Argument):
    pass

arg = click.argument("arg", cls=CustomArgument)

@click.command()
@arg
def c1(arg):
    pass

@click.command()
@arg
def c2(arg):
    pass

print("cls preserved:", type(c1.params[0]).__name__, type(c2.params[0]).__name__)
